package com.bank.deposit;

import java.util.logging.*;

public class MaxSumKDemo {
    private static final Logger log = Logger.getLogger(MaxSumKDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DepositStreakAnalyzer analyzer = new DepositStreakAnalyzer();

        int[] deposits = {20, 5, 30, 10, 50, 40, 15}; // in thousands
        long best = analyzer.bestKDayTotal(deposits, 3);
        log.info(() -> "Best 3-day deposit total: " + best);
    }
}

