class DepositStreakAnalyzer {
    private static final Logger log = Logger.getLogger(DepositStreakAnalyzer.class.getName());

    // Fixed-size window max sum. O(n) time, O(1) space.
    long bestKDayTotal(int[] a, int k) {
        if (k <= 0 || k > a.length) {
            log.warning(() -> "Invalid window size k=" + k);
            return Long.MIN_VALUE;
        }
        long sum = 0;
        for (int i = 0; i < k; i++) sum += a[i]; // initial window
        long best = sum;
        for (int r = k; r < a.length; r++) {
            sum += a[r] - a[r - k];               // add entering, drop leaving
            best = Math.max(best, sum);
        }
        return best;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
